using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.IO;
public static class IslandMountainFix {
 static Vector2[] route={new(-180,-205),new(-165,-155),new(-115,-120),new(-60,-130),new(-10,-95),new(35,-65),new(25,-15),new(40,35),new(90,45),new(145,60),new(165,115),new(205,155)};
 static float Sat(float a,float b,float v)=>Mathf.Clamp01((v-a)/(b-a));
 static float Dist(float x,float z){float d=999;for(int i=1;i<route.Length;i++){Vector2 v=route[i]-route[i-1],p=new Vector2(x,z);d=Mathf.Min(d,Vector2.Distance(p,route[i-1]+v*Mathf.Clamp01(Vector2.Dot(p-route[i-1],v)/v.sqrMagnitude)));}return d;}
 static float Peak(float x,float z,float cx,float cz,float r,float h){float dx=x-cx,dz=z-cz;float angle=Mathf.Atan2(dz,dx);float radius=Mathf.Sqrt(dx*dx+dz*dz)/(r*(1+.12f*Mathf.Sin(angle*5)+.07f*Mathf.Cos(angle*9)));float q=Mathf.Max(0,1-radius);return Mathf.Min(.82f,q)*h;}
 public static void Build(){EditorSceneManager.OpenScene("Assets/Scenes/Island_Surface_V02.unity");var t=Object.FindFirstObjectByType<Terrain>();var td=t.terrainData;var hs=td.GetHeights(0,0,513,513);var baseline=AssetDatabase.LoadAssetAtPath<TerrainData>("Assets/Island_Blockout_V01/Terrain.asset");var bh=baseline.GetHeights(0,0,513,513);int changed=0;float maxSlope=0;for(int z=0;z<513;z++)for(int x=0;x<513;x++){float xx=x/512f*720-360,zz=z/512f*720-360,old=bh[z,x]*180-25;if(old<8)continue;float target=old; if(zz>50 || (xx>140&&zz>90))hs[z,x]=bh[z,x];float mountain=Mathf.Max(Peak(xx,zz,-28,120,100,131),Mathf.Max(Peak(xx,zz,24,155,78,117),Peak(xx,zz,-65,160,68,103)));if(mountain>0){float ridge=mountain+11*(Mathf.PerlinNoise(xx*.09f+80,zz*.09f+80)-.5f);target=Mathf.Max(target,ridge); // broken southern escarpment with narrow toe and a 30m face
 float edge=68+9*Mathf.Sin(xx*.047f)+4*Mathf.Sin(xx*.13f);float along=Sat(-105,-65,xx)*(1-Sat(35,65,xx));float face=Sat(edge-6,edge+7,zz)*(1-Sat(100,125,zz))*along;target=Mathf.Max(target,old+face*24);
 }float dx=(xx-205)/70,dz=(zz-155)/72,r=Mathf.Sqrt(dx*dx+dz*dz);if(r<1.45f){float rim=1+.13f*Mathf.Sin(zz*.066f)+.08f*Mathf.Cos(xx*.09f);float plateau=72+4*Mathf.Sin(xx*.05f)+3*Mathf.Cos(zz*.08f);float raised=Mathf.Lerp(old,plateau,Sat(rim+.16f,rim-.07f,r));target=Mathf.Max(target,raised);}
 float protect=Sat(7,36,Dist(xx,zz)); // preserve the approved 14m main corridor exactly
 target=Mathf.Lerp(hs[z,x]*180-25,target,protect);if(Mathf.Abs(target-(hs[z,x]*180-25))>.02f){hs[z,x]=(target+25)/180;changed++;}}
 td.SetHeights(0,0,hs);var previous=td.terrainLayers; TerrainLayer sand=previous[0],grass=previous[2],soil=previous[3],rockLayer=previous[previous.Length-1];td.terrainLayers=new[]{sand,grass,soil,rockLayer};var alpha=new float[512,512,4];for(int z=0;z<512;z++)for(int x=0;x<512;x++){float xx=x/511f*720-360,zz=z/511f*720-360,slope=td.GetSteepness(x/511f,z/511f),h=td.GetInterpolatedHeight(x/511f,z/511f)-25;maxSlope=Mathf.Max(maxSlope,slope);float rock=Mathf.Max(Sat(25,48,slope),Sat(55,90,h))*.96f,beach=1-Sat(3,12,h),noise=Mathf.PerlinNoise(xx*.04f+20,zz*.04f+20);alpha[z,x,0]=beach*(1-rock);alpha[z,x,1]=(1-beach)*(1-rock)*(.75f+.15f*noise);alpha[z,x,2]=(1-beach)*(1-rock)*(.25f-.15f*noise);alpha[z,x,3]=rock;}td.SetAlphamaps(0,0,alpha);td.SetBaseMapDirty();t.basemapDistance=2000;t.heightmapPixelError=2;t.Flush();EditorUtility.SetDirty(td);
 var c=GameObject.Find("Overview angled").GetComponent<Camera>();c.orthographic=true;c.orthographicSize=315;c.transform.position=new(580,490,-650);c.transform.LookAt(new Vector3(0,35,30));Shot(c,"07_Relief_Overview");c.orthographic=false;c.fieldOfView=55;c.transform.position=new(-150,105,-55);c.transform.LookAt(new Vector3(-20,80,115));Shot(c,"08_Mountain_Escarpment");c.transform.position=new(345,115,80);c.transform.LookAt(new Vector3(205,70,155));Shot(c,"09_Lighthouse_Cliffs");c.orthographic=true;c.orthographicSize=320;c.transform.position=new(0,1000,0);c.transform.rotation=Quaternion.Euler(90,0,0);Shot(c,"01_Top");c.transform.position=new(580,490,-650);c.transform.LookAt(new Vector3(0,35,30));EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();File.WriteAllText("Docs/Island_Surface_V02/Relief-check.txt","Changed height samples: "+changed+"\nMaximum terrain slope: "+maxSlope+" degrees\nCoastal samples below 8m preserved. Main route within 7m preserved. V01 untouched.");Debug.Log("RELIEF_COMPLETE");}
 static void Shot(Camera c,string n){var rt=new RenderTexture(1600,1100,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var tex=new Texture2D(1600,1100,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1100),0,0);tex.Apply();File.WriteAllBytes("Docs/Island_Surface_V02/"+n+".png",tex.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;Object.DestroyImmediate(rt);Object.DestroyImmediate(tex);}
}
